  const input = readStdin()
  const records = splitRecords(input)

  const outLines = []

  for (let i = 0; i < records.length; i++) {
    const lineNo = i + 1
    const record = records[i]

    try {
      if (mode === 'normalize') {
        const parsed = parseURIReference(record)
        const normalized = normalizeParsed(parsed)
        outLines.push(serialize(normalized))
      } else {
        const spaceIdx = record.indexOf(' ')
