          fail(`line ${lineNo}: expected a base and a reference`)
          return
        }
        const baseStr = record.slice(0, spaceIdx)
        const refStr = record.slice(spaceIdx + 1)

        const base = parseURIReference(baseStr)
        if (base.scheme === undefined) {
          fail(`line ${lineNo}: the base has no scheme`)
          return
        }
        const ref = parseURIReference(refStr)

        const resolved = resolveReference(base, ref)
        const normalized = normalizeParsed(resolved)
        outLines.push(serialize(normalized))
      }
    } catch (err) {
      if (err && err.component) {
        fail(`line ${lineNo}: the ${err.component} has a truncated percent-encoding`)
        return
      }
      throw err
    }
  }

  const output = outLines.length === 0 ? '' : outLines.join('\n') + '\n'
  process.stdout.write(output)
  process.exit(0)
}

